const out=path.resolve(process.env.GUS_DISCOVER_BUILD_DIR||'/tmp/gus-discover-design');
fs.mkdirSync(path.join(out,'QA'),{recursive:true});fs.mkdirSync(path.join(out,'Previews'),{recursive:true});
const g=new SceneGraph(), first=g.getPages()[0];
g.updateNode(first.id,{name:'01 · Discover & Requests'});
const pages=[first,g.addPage('02 · Manage & Recovery'),g.addPage('03 · iPad & Mac'),g.addPage('04 · TV & Vision'),g.addPage('05 · Components'),g.addPage('06 · Read Me')];
