const palettes={Dark:{bg:'#101214',surface:'#1D2023',inset:'#292D31',text:'#F6F7F8',secondary:'#B0B9BE',accent:'#B8E3E9',ink:'#0B2E33',line:'#3B4248',positive:'#A0DFC3',warning:'#F1CD89',bad:'#FFB4AD'},Light:{bg:'#FFFFFF',surface:'#F2F4F5',inset:'#E5EAEC',text:'#161D21',secondary:'#56656D',accent:'#315F67',ink:'#FFFFFF',line:'#CCD4D8',positive:'#245C44',warning:'#775416',bad:'#AA322E'}};
let c=palettes.Dark;
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const text=(s,size=17,color=c.text,weight=400,w='fill',extra='')=>`<Text name="${esc(String(s).slice(0,70))}" font="SF Pro" size={${size}} lineHeight={${Math.ceil(size*1.28)}} weight={${weight}} color="${color}" w=${typeof w==='number'?`{${w}}`:JSON.stringify(w)} ${extra}>${esc(s)}</Text>`;
const frame=(name,w,h,body,props='')=>`<Frame name="${esc(name)}" w=${typeof w==='number'?`{${w}}`:JSON.stringify(w)} h=${typeof h==='number'?`{${h}}`:JSON.stringify(h)} ${props}>${body}</Frame>`;
const col=(name,w,body,gap=12,props='')=>frame(name,w,'hug',body,`flex="col" gap={${gap}} ${props}`);
const row=(name,w,body,gap=12,props='')=>frame(name,w,'hug',body,`flex="row" gap={${gap}} items="center" ${props}`);
const at=(x,y,w,h,body,name='Position')=>frame(name,w,h,body,`x={${x}} y={${y}}`);
