const pill=(s,color=c.secondary,bg=c.surface)=>frame('Status · '+s,'hug',28,text(s,12,color,600,Math.ceil(s.length*7.2+(s.length<=8?14:0))),`flex="row" items="center" px={10} rounded={14} bg="${bg}"`);
const divider=()=>frame('Separator','fill',1,'',`bg="${c.line}"`);
const svg=(name,size,paths,color=c.text)=>`<svg name="${name}" viewBox="0 0 24 24" size={${size}}>${paths.map(d=>`<path d="${d}" stroke="${color}" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" fill="none" />`).join('')}</svg>`;
