const bad=[...g.getAllNodes()].filter(n=>['x','y','width','height'].some(k=>!Number.isFinite(n[k]))||n.type==='TEXT'&&n.width<1);if(bad.length)throw Error('Invalid geometry '+bad.slice(0,5).map(n=>n.name));
const descendant=id=>g.getChildren(id).flatMap(n=>[n,...descendant(n.id)]);
for(const m of manifest){const origin=g.getAbsolutePosition(m.id);m.links=descendant(m.id).filter(n=>n.name.startsWith('[go:')).map(n=>{const a=g.getAbsolutePosition(n.id);let box={x:a.x,y:a.y,w:n.width,h:n.height},parent=g.getNode(n.parentId);while(parent){if(parent.clipsContent){const q=g.getAbsolutePosition(parent.id),right=Math.min(box.x+box.w,q.x+parent.width),bottom=Math.min(box.y+box.h,q.y+parent.height);box.x=Math.max(box.x,q.x);box.y=Math.max(box.y,q.y);box.w=Math.max(0,right-box.x);box.h=Math.max(0,bottom-box.y);}parent=g.getNode(parent.parentId);}return {target:n.name.match(/^\[go:([^\]]+)/)[1],x:box.x-origin.x,y:box.y-origin.y,w:box.w,h:box.h};}).filter(n=>n.w>0&&n.h>0&&n.x+n.w>0&&n.y+n.h>0&&n.x<m.w&&n.y<m.h);}
