const summary={artboards:manifest.length,pages:pages.map(p=>({id:p.id,name:p.name})),nodes:[...g.getAllNodes()].length,textLayers:[...g.getAllNodes()].filter(n=>n.type==='TEXT').length,components:[...g.getAllNodes()].filter(n=>n.type==='COMPONENT').length,instances:[...g.getAllNodes()].filter(n=>n.type==='INSTANCE').length,autoLayouts:[...g.getAllNodes()].filter(n=>n.layoutMode!=='NONE').length,colorVariables:colorVars.size,textStyles:styleIds.size,bytes:data.length,geometry:'finite / positive text widths',appSource:'d715c05'};
